        address indexed contractAddress,
        uint createdAt,
        BaseMetadata metadata
    );
    struct Metadata {
        address contractAddress;
        uint createdAt;
        BaseMetadata metadata;
    }
    Metadata[] s_contractsCreated;

    function createLottery(
        string memory _title,
        string memory _description,
        uint _eventDate,
        uint _secondsToEvent,
        uint _numTickets,
        uint _ticketPrice,
        address _vrfCoordinator,
        uint _subscriptionId,
        bytes32 _keyHash
    ) external payable {
        uint prize = msg.value;
        address owner = msg.sender;

        Lottery newLottery = new Lottery{value: prize}(
            owner,
            _secondsToEvent,
            _numTickets,
            _ticketPrice,
            _vrfCoordinator,
            _subscriptionId,
            _keyHash
        );
        address contractAddress = address(newLottery);

        BaseMetadata memory baseMetadata = BaseMetadata({
            title: _title,
            description: _description,
            owner: owner,
            eventDate: _eventDate,
            numTickets: _numTickets,
            ticketPrice: _ticketPrice,
            prize: prize
        });
        uint createdAt = block.timestamp;
        emit NewLottery(contractAddress, createdAt, baseMetadata);
        s_contractsCreated.push(
            Metadata({
                contractAddress: contractAddress,
                createdAt: createdAt,
                metadata: baseMetadata
            })
        );
    }

    function contractsCreated() external view returns (Metadata[] memory) {
        return s_contractsCreated;
    }
}

